        dy = points[j][1] - points[i][1];
      if (dx === 0 && dy === 0) {
        duplicates++;
        continue;
      }
      const divisor = gcd(Math.abs(dx), Math.abs(dy));
      dx /= divisor;
      dy /= divisor;
      if (dx < 0 || (dx === 0 && dy < 0)) {
        dx = -dx;
        dy = -dy;
      }
      const slope = dx + "," + dy,
        count = (counts.get(slope) || 0) + 1;
