  for (let c = 0; c < columns; c++) {
    add(0, c);
    add(rows - 1, c);
  }
  for (let head = 0; head < queue.length; head++) {
    const [r, c] = queue[head];
    add(r - 1, c);
    add(r + 1, c);
    add(r, c - 1);
    add(r, c + 1);
  }
  for (let r = 0; r < rows; r++)
    for (let c = 0; c < columns; c++) if (board[r][c] === "W" && !safe[r][c]) board[r][c] = "B";
  return board;
