    if (this.first > 1024 && this.first * 2 > this.candidates.length) {
      this.candidates = this.candidates.slice(this.first);
      this.first = 0;
    }
    return value;
  }
  max() {
    if (this.head === this.values.length) throw new RangeError("Empty queue");
    return this.candidates[this.first];
  }
