    {
        var output = new System.Text.StringBuilder();
        int count = 0;
        foreach (char c in encoded)
        {
            if (c >= '0' && c <= '9')
                count = count * 10 + c - '0';
            else
            {
                output.Append(c, count);
                count = 0;
            }
        }
        return output.ToString();
    }
}

