        for (int i = next; i < A.Count; i += 2)
        {
            int low, high;
            if (A[i] < A[i + 1])
            {
                low = A[i];
                high = A[i + 1];
            }
            else
            {
                low = A[i + 1];
                high = A[i];
            }
            if (low < minimum)
                minimum = low;
            if (high > maximum)
                maximum = high;
        }
        return (minimum, maximum);
    }
}

