function sortKIncreasingDecreasingArray(A) {
  class Heap {
    constructor(compare) {
      this.a = [];
      this.compare = compare;
    }
    get size() {
      return this.a.length;
    }
    peek() {
      return this.a[0];
    }
    push(value) {
      const a = this.a;
      a.push(value);
      let i = a.length - 1;
      while (i) {
        const p = Math.floor((i - 1) / 2);
        if (this.compare(a[p], a[i]) <= 0) break;
        [a[p], a[i]] = [a[i], a[p]];
        i = p;
      }
    }
    pop() {
      const a = this.a;
      if (!a.length) throw new RangeError("Empty heap");
      const result = a[0],
        last = a.pop();
      if (a.length) {
        a[0] = last;
        let i = 0;
        for (;;) {
          let c = 2 * i + 1;
          if (c >= a.length) break;
          if (c + 1 < a.length && this.compare(a[c + 1], a[c]) < 0) c++;
          if (this.compare(a[i], a[c]) <= 0) break;
          [a[i], a[c]] = [a[c], a[i]];
          i = c;
        }
      }
      return result;
    }
  }
  const runs = [];
  for (let start = 0; start < A.length; ) {
    let end = start + 1;
    const increasing = end === A.length || A[end] >= A[start];
    while (end < A.length && (increasing ? A[end] >= A[end - 1] : A[end] <= A[end - 1])) end++;
    const run = A.slice(start, end);
    if (!increasing) run.reverse();
    runs.push(run);
    start = end;
  }
  const candidates = new Heap((a, b) => a.value - b.value),
    result = [];
  for (let i = 0; i < runs.length; i++) candidates.push({ run: i, position: 0, value: runs[i][0] });
  while (candidates.size) {
    const entry = candidates.pop();
    result.push(entry.value);
    const next = entry.position + 1;
    if (next < runs[entry.run].length)
      candidates.push({
        run: entry.run,
        position: next,
        value: runs[entry.run][next],
      });
  }
  return result;
}

