function solveSudoku(board) {
  const n = board.length,
    width = Math.sqrt(n),
    rows = Array.from({ length: n }, () => Array(n + 1).fill(false)),
    columns = Array.from({ length: n }, () => Array(n + 1).fill(false)),
    blocks = Array.from({ length: n }, () => Array(n + 1).fill(false));
  const box = (r, c) => Math.floor(r / width) * width + Math.floor(c / width);
  for (let r = 0; r < n; r++)
    for (let c = 0; c < n; c++)
      if (board[r][c])
        rows[r][board[r][c]] = columns[c][board[r][c]] = blocks[box(r, c)][board[r][c]] = true;
  function fill() {
    let row = -1,
      column = -1,
      choices = null;
    for (let r = 0; r < n; r++)
      for (let c = 0; c < n; c++)
        if (!board[r][c]) {
          const options = [];
          for (let value = 1; value <= n; value++)
            if (!rows[r][value] && !columns[c][value] && !blocks[box(r, c)][value])
              options.push(value);
          if (!options.length) return false;
          if (choices === null || options.length < choices.length) {
            row = r;
            column = c;
            choices = options;
          }
        }
    if (row < 0) return true;
    const b = box(row, column);
    for (const value of choices) {
      board[row][column] = value;
      rows[row][value] = columns[column][value] = blocks[b][value] = true;
      if (fill()) return true;
      rows[row][value] = columns[column][value] = blocks[b][value] = false;
      board[row][column] = 0;
    }
    return false;
  }
  if (!fill()) throw new Error("No Sudoku solution");
}

import itertools

import math

from typing import List


def solve_sudoku(partial_assignment: List[List[int]]) -> bool:
    def solve_partial_sudoku(i, j):
        if i == len(partial_assignment):
            i = 0  # Starts a row.
            j += 1
            if j == len(partial_assignment[i]):
                return True  # Entire matrix has been filled without conflict.

        # Skips nonempty entries.
        if partial_assignment[i][j] != empty_entry:
            return solve_partial_sudoku(i + 1, j)

        def valid_to_add(i, j, val):
            # Check row constraints.
            if any(val == partial_assignment[k][j] for k in range(len(partial_assignment))):
                return False

            # Check column constraints.
            if val in partial_assignment[i]:
                return False

            # Check region constraints.
            region_size = int(math.sqrt(len(partial_assignment)))
            I = i // region_size
            J = j // region_size
            return not any(
                val == partial_assignment[region_size * I + a][region_size * J + b]
                for a, b in itertools.product(range(region_size), repeat=2)
            )

        for val in range(1, len(partial_assignment) + 1):
            # It's substantially quicker to check if entry val with any of the
            # constraints if we add it at (i,j) adding it, rather than adding it and
            # then checking all constraints. The reason is that we know we are
            # starting with a valid configuration, and the only entry which can
            # cause a problem is entry val at (i,j).
            if valid_to_add(i, j, val):
                partial_assignment[i][j] = val
                if solve_partial_sudoku(i + 1, j):
                    return True
        partial_assignment[i][j] = empty_entry  # Undo assignment.
        return False

    empty_entry = 0
    return solve_partial_sudoku(0, 0)

