def merge_two_sorted_arrays(A: List[int], m: int, B: List[int], n: int) -> None:

    a, b, write_idx = m - 1, n - 1, m + n - 1
    while a >= 0 and b >= 0:
        if A[a] > B[b]:
            A[write_idx] = A[a]
            a -= 1
